const API = location.port === "3000" ? "http://localhost:8000/api" : "/api";
const $ = (selector) => document.querySelector(selector);
const state = { farmer: JSON.parse(localStorage.getItem("rythu-farmer") || "null"), crop: null, language: localStorage.getItem("rythu-language") || "English", location: null, photo: null, mode: localStorage.getItem("rythu-mode") || "farm" };
let weatherTimer = null;
const translations = {
  English: { dashboard:"Dashboard", farm:"My Farm", care:"Crop Care", market:"Market", storage:"Storage", logistics:"Logistics", weather:"Weather", profile:"Profile", login:"Login", register:"Create account", tagline:"Your farm journey, in one trusted place." },
  Telugu: { dashboard:"డాష్‌బోర్డ్", farm:"నా పొలం", care:"పంట సంరక్షణ", market:"మార్కెట్", storage:"నిల్వ", logistics:"రవాణా", weather:"వాతావరణం", profile:"ప్రొఫైల్", login:"లాగిన్", register:"ఖాతా సృష్టించండి", tagline:"మీ వ్యవసాయ ప్రయాణం కోసం ఒకే నమ్మకమైన చోటు." }
};
document.head.insertAdjacentHTML("beforeend", `<style>
.auth-screen{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 80% 15%,#cce98c 0,transparent 30%),#103d2e}.auth-screen.hidden{display:none}.auth-card{width:min(430px,100%);padding:34px;border-radius:18px;background:#fffdf8;box-shadow:0 20px 80px #001f134d;text-align:center}.auth-card h1{font-size:34px;color:#15563f}.auth-card p{color:#637667}.auth-mark{margin:auto;background:#dff0bb;color:#15563f;border-radius:50%;display:grid;place-content:center;width:58px;height:58px;font-size:28px}.lang-switch{display:flex;justify-content:center;gap:8px;margin:22px 0}.lang-switch button{background:#eff4e9;border:1px solid #dce8d4;border-radius:18px;padding:8px 14px;color:#185740}.auth-action{display:block;width:100%;margin:10px 0}.auth-form{display:grid;text-align:left;gap:7px;margin-top:18px}.auth-form label{font-size:13px;font-weight:700;color:#526354}.auth-form input{margin:5px 0 7px}.auth-form .text{text-align:center;margin-top:8px}.auth-help{font-size:12px;margin-top:18px}.hidden{display:none!important}body:has(.auth-screen:not(.hidden)) #appShell,body:has(.auth-screen:not(.hidden)) #appSide{filter:blur(4px);pointer-events:none}.editor-grid,.storage-controls{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.editor-grid label{font-size:12px;font-weight:700;color:#526354}.editor-grid input,.editor-grid select,.editor-grid textarea{width:100%;margin-top:5px}.editor-grid .wide{grid-column:1/-1}.editor-dialog{border:0;border-radius:13px;width:min(720px,94vw);padding:26px;box-shadow:0 20px 70px #0006}.editor-dialog::backdrop{background:#103d3099}.listing-panel{margin:18px 0}.listing-result{margin-top:12px;background:#edf6df;padding:12px;border-radius:8px}.resource-note{font-size:11px!important;color:#728071!important}.source-badge{font-size:10px;font-weight:800;color:#396a41;background:#e3f1dc;padding:6px 8px;border-radius:12px;height:max-content;white-space:nowrap}.resource-title{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.maps-link{align-self:center;white-space:nowrap;text-decoration:none;background:#e6f0d5;color:#185740;padding:10px 12px;border-radius:6px;font-size:13px;font-weight:800}.empty-state{padding:22px;border:1px dashed #bed3b9;border-radius:8px;color:#617561;background:#fbfdf8;line-height:1.5}@media(max-width:650px){.editor-grid,.storage-controls{grid-template-columns:1fr}.auth-card{padding:27px 21px}.maps-link{align-self:flex-start}}</style>`);
const toast = (message) => { const el=$("#toast"); el.textContent=message; el.classList.add("show"); setTimeout(()=>el.classList.remove("show"),3500); };
const safe = (value) => String(value ?? "").replace(/[&<>"']/g, c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
async function call(path, options={}) {
  const isForm = options.body instanceof FormData;
  const response = await fetch(API + path, { ...options, headers: isForm ? options.headers : {"Content-Type":"application/json", ...(options.headers||{})} });
  if (!response.ok) { const data=await response.json().catch(()=>({detail:"Request failed"})); throw Error(typeof data.detail==="string"?data.detail:"Please check the entered information."); }
  return response.json();
}
function applyLanguage() {
  localStorage.setItem("rythu-language", state.language); document.documentElement.lang=state.language==="Telugu"?"te":"en";
  const t=translations[state.language]; document.querySelectorAll("[data-t]").forEach(el=>el.textContent=t[el.dataset.t]||el.textContent);
  $("#authTagline").textContent=t.tagline; $("#showLogin").textContent=t.login; $("#showRegister").textContent=t.register;
  $("#language").textContent=state.language==="English"?"English / తెలుగు":"తెలుగు / English";
  const labels = state.language==="Telugu"
    ? {dashboard:"ఈ రోజు మీ దృష్టికి ఏమి కావాలి?",passport:"నా పొలం మరియు పంట వివరాలు",care:"మీ పంటను తనిఖీ చేయండి",market:"మీ విక్రయాన్ని స్పష్టంగా ప్లాన్ చేయండి.",storage:"మీ పొలం దగ్గర నిల్వను కనుగొనండి.",logistics:"మీ పంటను తరలించండి."}
    : {dashboard:"What needs your attention?",passport:"North field · Tomato",care:"Check your crop",market:"Plan your sale, clearly.",storage:"Find storage near your farm.",logistics:"Move your harvest."};
  ["dashboard","passport","care","market","storage","logistics"].forEach(id=>{const heading=$("#"+id+" .view-heading h2")||$("#"+id+" h1");if(heading&&labels[id])heading.textContent=labels[id];});
  const fieldLabels = state.language==="Telugu"
    ? {loginPhone:"మొబైల్ నంబర్",loginPin:"పిన్",registerName:"పూర్తి పేరు",registerPhone:"మొబైల్ నంబర్",registerVillage:"గ్రామం",registerPin:"పిన్",registerConfirmPin:"పిన్ నిర్ధారించండి"}
    : {loginPhone:"Mobile number",loginPin:"PIN",registerName:"Full name",registerPhone:"Mobile number",registerVillage:"Village",registerPin:"PIN",registerConfirmPin:"Confirm PIN"};
  Object.entries(fieldLabels).forEach(([id,label])=>{const input=$("#"+id);if(input&&input.parentNode.firstChild)input.parentNode.firstChild.textContent=label;});
  $("#loginForm button[type=submit]").textContent=state.language==="Telugu"?"లాగిన్ →":"Login →";
  $("#registerForm button[type=submit]").textContent=state.language==="Telugu"?"ఖాతా సృష్టించండి →":"Create account →";
}
function showAuth(panel) { ["welcomeForm","loginForm","registerForm"].forEach(id=>$("#"+id).classList.toggle("hidden", id!==panel)); }
function bindAuth() {
  if(!$("#demoLogin")) $("#showRegister").insertAdjacentHTML("afterend",'<button class="text auth-action" id="demoLogin" type="button">Continue with demo account →</button>');
  $("#showLogin").onclick=()=>showAuth("loginForm"); $("#showRegister").onclick=()=>showAuth("registerForm");
  $("#demoLogin").onclick=async()=>{try{const data=await call("/auth/login",{method:"POST",body:JSON.stringify({phone:"9000000000",pin:"1234"})});startApp(data.farmer);}catch(error){toast(error.message)}};
  document.querySelectorAll(".switch-auth").forEach(button=>button.onclick=()=>showAuth(button.dataset.show));
  document.querySelectorAll("[data-lang]").forEach(button=>button.onclick=()=>{state.language=button.dataset.lang;applyLanguage();});
  $("#loginForm").onsubmit=async(event)=>{event.preventDefault();try{const data=await call("/auth/login",{method:"POST",body:JSON.stringify({phone:$("#loginPhone").value.trim(),pin:$("#loginPin").value})});startApp(data.farmer)}catch(error){toast(error.message)}};
  $("#registerForm").onsubmit=async(event)=>{event.preventDefault();if($("#registerPin").value!==$("#registerConfirmPin").value){toast("PIN and Confirm PIN must match.");return}try{const data=await call("/auth/register",{method:"POST",body:JSON.stringify({name:$("#registerName").value.trim(),phone:$("#registerPhone").value.trim(),village:$("#registerVillage").value.trim(),pin:$("#registerPin").value,language:state.language})});startApp(data.farmer);toast(data.message)}catch(error){toast(error.message)}};
}
async function startApp(farmer) {
  state.farmer=farmer; localStorage.setItem("rythu-farmer",JSON.stringify(farmer)); $("#authScreen").classList.add("hidden"); $("#farmName").textContent=farmer.name+"’s Farm"; applyLanguage();
  await loadCrop(); renderProfile(); await loadPassport(); await loadDashboard();
}
async function loadCrop() { const crops=await call("/crops?farmer_id="+state.farmer.id); state.crop=crops[0]||null; }
function view(name) { document.querySelectorAll(".view").forEach(el=>el.classList.toggle("active",el.id===name)); document.querySelectorAll(".side nav button").forEach(el=>el.classList.toggle("active",el.dataset.view===name)); $("#appSide").classList.remove("open"); if(name==="passport")loadPassport(); if(name==="market")loadMarket(); if(name==="storage")loadStorage(); if(name==="logistics")loadLogistics(); if(name==="weather")loadWeather(); }
document.querySelectorAll("[data-view]").forEach(button=>button.onclick=()=>view(button.dataset.view));
document.querySelectorAll(".go-care").forEach(button=>button.onclick=()=>view("care")); document.querySelectorAll(".go-market").forEach(button=>button.onclick=()=>view("market")); $("#menu").onclick=()=>$("#appSide").classList.toggle("open");
$("#language").onclick=async()=>{state.language=state.language==="English"?"Telugu":"English";applyLanguage();renderProfile();if(state.farmer){try{state.farmer=await call("/farmers/"+state.farmer.id+"/preferences",{method:"PUT",body:JSON.stringify({language:state.language})});localStorage.setItem("rythu-farmer",JSON.stringify(state.farmer));}catch(error){toast(error.message)}}}; $("#logout").onclick=()=>{localStorage.removeItem("rythu-farmer"); state.farmer=null; state.crop=null; $("#authScreen").classList.remove("hidden");showAuth("welcomeForm");};
async function loadDashboard() { if(!state.crop)return; $("#plantDate").textContent=state.crop.planting_date; $("#cropAge").textContent=state.crop.crop_age_days; }
async function loadPassport() {
  if(!state.crop)return; const crop=await call("/crops/"+state.crop.id); state.crop=crop;
  $("#timeline").innerHTML=crop.passport.map(item=>`<div class="timeline-item"><b>${safe(item.type)} · ${safe(item.status)}</b><small>${safe(item.date)}</small><p>${safe(item.note)}</p></div>`).join("");
  document.querySelector("#passport .passport-crop h3").textContent=`${crop.variety} ${crop.name}`;
  document.querySelector("#passport .passport-crop p").innerHTML=`${crop.area_acres} acres · planted ${safe(crop.planting_date)} · <b>${crop.crop_age_days}</b> days old`;
}
function editPassport() {
  const c=state.crop; const dialog=document.createElement("dialog"); dialog.className="editor-dialog"; dialog.innerHTML=`<button class="close">×</button><p class="label">EDIT CROP PASSPORT</p><h2>Crop details</h2><form id="passportForm" class="editor-grid"><label>Crop name<input name="name" value="${safe(c.name)}" required></label><label>Variety<input name="variety" value="${safe(c.variety)}" required></label><label>Field<input name="field_name" value="${safe(c.field_name)}" required></label><label>Area (acres)<input name="area_acres" type="number" step=".01" min=".01" value="${c.area_acres}" required></label><label>Date planted<input name="planting_date" type="date" value="${c.planting_date}" required></label><label>Expected harvest<input name="expected_harvest_date" type="date" value="${c.expected_harvest_date||""}"></label><label>Actual harvest<input name="actual_harvest_date" type="date" value="${c.actual_harvest_date||""}"></label><label>Expected quantity (kg)<input name="harvest_quantity_kg" type="number" min="0" value="${c.harvest_quantity_kg||0}"></label><label>Actual yield (kg)<input name="actual_yield_kg" type="number" min="0" value="${c.actual_yield_kg||""}"></label><label>Health status<select name="health_status"><option>${safe(c.health_status)}</option><option>Healthy</option><option>Attention</option><option>Not recorded</option></select></label><label>Market status<input name="market_status" value="${safe(c.market_status)}"></label><label>Storage status<input name="storage_status" value="${safe(c.storage_status||"Not arranged")}"></label><label>Selling status<input name="selling_status" value="${safe(c.selling_status||"Not listed")}"></label><label class="wide">Notes<textarea name="notes">${safe(c.notes||"")}</textarea></label><button class="primary wide" type="submit">Save crop passport</button></form>`; document.body.append(dialog); dialog.showModal(); dialog.querySelector(".close").onclick=()=>dialog.close();
  dialog.querySelector("form").onsubmit=async(event)=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.target));["area_acres","harvest_quantity_kg","actual_yield_kg"].forEach(key=>{data[key]=data[key]===""?null:Number(data[key])});["expected_harvest_date","actual_harvest_date"].forEach(key=>{data[key]=data[key]||null});try{await call("/crops/"+c.id,{method:"PUT",body:JSON.stringify(data)});dialog.close();await loadPassport();toast("Crop passport saved.");}catch(error){toast(error.message)}}; }
$("#editCrop").onclick=editPassport;
function renderProfile() { if(!state.farmer)return; document.querySelector("#profile .profile-card div").innerHTML=`<h3>${safe(state.farmer.name)}</h3><p>${safe(state.farmer.village)} · Small & marginal farmer</p><p>Language: ${state.language==="Telugu"?"తెలుగు":"English"}</p>`; }
$("#photo").onchange=event=>{state.photo=event.target.files[0]||null;$("#photoName").textContent=state.photo?state.photo.name:"No photo selected";};
$("#diagnose").onclick=async()=>{if(!state.photo){toast("Choose a crop image first.");return}const button=$("#diagnose");button.disabled=true;button.textContent="Analyzing…";try{const form=new FormData();form.append("crop_id",state.crop.id);form.append("image",state.photo);const data=await call("/diagnose/upload",{method:"POST",body:form});$("#diagnosisResult").innerHTML=`<p class="label">MODEL RESULT</p><h3>${safe(data.diagnosis)}</h3><p class="confidence">${Math.round(data.confidence*100)}% confidence</p><p>${safe(data.recommended_action)}</p>${data.expert_review_recommended?'<p class="expert-note">AI is uncertain. Expert review recommended.</p>':""}<small>${safe(data.disclaimer)}</small>`;await loadPassport();}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent="Analyze crop image";}};
async function loadMarket() {
  const prices=await call("/market/prices"); $("#prices").innerHTML=prices.map(p=>`<div class="resource"><div><h3>${safe(p.crop)} · ${safe(p.market)}</h3><p>${safe(p.label)}</p></div><b>₹${p.price_per_kg}/kg</b></div>`).join(""); renderListing(); matchBuyers();
}
function renderListing() {
  const c=state.crop; let panel=$("#marketListingPanel"); if(!panel){panel=document.createElement("section");panel.id="marketListingPanel";panel.className="panel listing-panel";$("#market").insertBefore(panel,$("#market .top-space"));}
  panel.innerHTML=`<p class="label">MY PRODUCE LISTING</p><h3>Prepare your sale</h3><form id="listingForm" class="editor-grid"><label>Crop<select name="name"><option>${safe(c.name)}</option><option>Tomato</option><option>Chilli</option><option>Onion</option><option>Rice</option></select></label><label>Quantity (kg)<input name="harvest_quantity_kg" type="number" min="0" value="${c.harvest_quantity_kg||0}"></label><label>Asking price ₹/kg<input name="asking_price_per_kg" type="number" step=".01" min="0" value="${c.asking_price_per_kg||""}"></label><label>Expected selling date<input name="expected_selling_date" type="date" value="${c.expected_selling_date||""}"></label><label>Quality / grade<input name="quality_grade" value="${safe(c.quality_grade||"")}"></label><label>Selling status<select name="selling_status"><option>${safe(c.selling_status||"Not listed")}</option><option>Not listed</option><option>Listed</option><option>Sold</option></select></label><label class="wide">Notes<textarea name="market_notes">${safe(c.market_notes||"")}</textarea></label><button class="text" id="editListing" type="button">Edit listing</button><button class="secondary" type="submit">Save listing</button><button class="primary" id="sellList" type="button">Sell / List crop</button></form><div id="listingValue" class="listing-result"></div>`;
  const updateValue=()=>{const q=Number(panel.querySelector("[name=harvest_quantity_kg]").value)||0,p=Number(panel.querySelector("[name=asking_price_per_kg]").value)||0;$("#listingValue").textContent=`Estimated total value: ₹${(q*p).toLocaleString()} (your asking-price estimate)`;}; updateValue(); panel.querySelectorAll("input").forEach(input=>input.oninput=updateValue);
  panel.querySelector("form").onsubmit=event=>saveListing(event,false); $("#sellList").onclick=event=>saveListing(event,true); $("#editListing").onclick=()=>panel.querySelector("[name=harvest_quantity_kg]").focus();
}
async function saveListing(event,list) { event.preventDefault(); const form=$("#listingForm"); const data=Object.fromEntries(new FormData(form)); data.harvest_quantity_kg=Number(data.harvest_quantity_kg)||0;data.asking_price_per_kg=data.asking_price_per_kg===""?null:Number(data.asking_price_per_kg);data.expected_selling_date=data.expected_selling_date||null;if(list)data.selling_status="Listed";try{state.crop=await call("/crops/"+state.crop.id,{method:"PUT",body:JSON.stringify(data)});renderListing();toast(list?"Crop listed in your local Rythu Sodara records.":"Listing saved.");}catch(error){toast(error.message)}}
async function matchBuyers(){const items=await call("/buyers/match",{method:"POST",body:JSON.stringify({crop:state.crop.name,quantity_kg:state.crop.harvest_quantity_kg||1})});$("#buyerMatches").innerHTML=items.map(x=>`<div class="match"><div><h4>${safe(x.buyer.name)} · ₹${x.buyer.price_per_kg}/kg</h4><p>${x.why_matched.map(safe).join(" · ")}</p></div><span class="score">${x.match_score}% match</span></div>`).join("")||'<div class="empty-state">No buyer matches for this crop yet.</div>'; }
$("#matchBuyers").onclick=()=>matchBuyers().then(()=>toast("Buyer matches refreshed."));
$("#calculate").onclick=async()=>{try{const d=await call("/sell-vs-store",{method:"POST",body:JSON.stringify({quantity_kg:+$("#qty").value,current_price_per_kg:+$("#nowPrice").value,future_price_per_kg:+$("#futurePrice").value,storage_cost_per_kg_day:+$("#storageCost").value,transport_cost:+$("#transport").value,duration_days:+$("#duration").value})});$("#calcResult").innerHTML=`<b>Sell now: ₹${d.sell_now_gross.toLocaleString()}</b><br>Store scenario net: ₹${d.estimated_store_net.toLocaleString()}<br><b>Difference: ₹${d.difference.toLocaleString()}</b><br><small>${safe(d.label)}</small>`;}catch(error){toast(error.message)}};
async function loadStorage(){const s=await call("/storage");$("#storageList").innerHTML=s.map(x=>`<div class="resource"><div><h3>${safe(x.name)}</h3><p>${safe(x.storage_type)} · ${x.distance_km} km · ${x.available_capacity_kg.toLocaleString()} kg available</p><p class="resource-note">Rythu Sodara database listing</p></div><b>₹${x.cost_per_kg_day}/kg/day</b></div>`).join("");}
function showNearby(items){$("#nearbyStorage").innerHTML=items.length?items.map(x=>`<article class="resource"><div><div class="resource-title"><h3>${safe(x.name)}</h3><span class="source-badge">OpenStreetMap</span></div><p>${safe(x.type)} · <b>${x.distance_km} km away</b></p>${x.address?`<p>📍 ${safe(x.address)}</p>`:"<p>Address not mapped in OpenStreetMap.</p>"}<p class="resource-note">No capacity, price, or availability is assumed.</p></div><a class="maps-link" href="${safe(x.maps_url)}" target="_blank" rel="noopener">Open in Maps ↗</a></article>`).join(""):'<div class="empty-state">No mapped warehouse was found in this radius.</div>';}
async function searchNearby(lat,lon){const b=$("#searchNearby");b.disabled=true;b.textContent="Searching…";try{const result=await call(`/storage/nearby?lat=${lat}&lon=${lon}&radius_km=${$("#storageRadius").value}`);showNearby(result);$("#locationStatus").textContent="📍 Location detected — results from OpenStreetMap.";}catch(error){$("#nearbyStorage").innerHTML='<div class="empty-state">Nearby search is unavailable. Use Rythu Sodara matched storage below.</div>';toast(error.message);}finally{b.disabled=false;b.textContent="Search nearby storage";}}
$("#useLocation").onclick=()=>{if(!navigator.geolocation){$("#locationStatus").textContent="Location is not supported. Search by village/city instead.";return}$("#locationStatus").textContent="Requesting location permission…";navigator.geolocation.getCurrentPosition(p=>{state.location={lat:p.coords.latitude,lon:p.coords.longitude};searchNearby(state.location.lat,state.location.lon)},()=>$("#locationStatus").textContent="Location was not shared. Search by village/city instead.");};
$("#searchNearby").onclick=async()=>{if(state.location)return searchNearby(state.location.lat,state.location.lon);const place=$("#storagePlace").value.trim();if(!place){toast("Use your location or enter a village/city.");return}try{const p=await call("/storage/geocode?query="+encodeURIComponent(place));state.location={lat:p.latitude,lon:p.longitude};await searchNearby(p.latitude,p.longitude);}catch(error){toast(error.message)}};
$("#matchStorage").onclick=async()=>{try{const matches=await call("/storage/match",{method:"POST",body:JSON.stringify({crop:state.crop.name,quantity_kg:state.crop.harvest_quantity_kg||1})});$("#storageList").innerHTML=matches.map(x=>`<article class="resource"><div><h3>${safe(x.facility)}</h3><p>${x.distance_km} km · ${x.available_capacity_kg.toLocaleString()} kg · ₹${x.cost_per_kg_day}/kg/day</p><p class="resource-note">${safe(x.reason)}</p></div><span class="score">${x.score}% match</span></article>`).join("")||'<div class="empty-state">No matching storage found.</div>';}catch(error){toast(error.message)}};
async function loadLogistics(){const data=await call("/logistics");$("#logisticsList").innerHTML=data.map(x=>`<div class="resource"><div><h3>${safe(x.name)} · ${safe(x.vehicle_type)}</h3><p>${x.capacity_kg} kg capacity · ${safe(x.location)} · ${x.available?"Available":"Unavailable"}</p></div><b>₹${x.cost}</b></div>`).join("");}
$("#matchLogistics").onclick=()=>loadLogistics();
function network(){const online=navigator.onLine;$("#networkStatus").textContent=online?"● Online":"● Offline — saving locally";}addEventListener("online",network);addEventListener("offline",network);
function setupWeatherUI() {
  document.head.insertAdjacentHTML("beforeend",'<style>.weather-actions{display:flex;gap:10px;flex-wrap:wrap}.weather-content{margin-top:18px}.weather-current{background:linear-gradient(130deg,#155b42,#2f815c);color:#fff;border-radius:14px;padding:25px;display:grid;grid-template-columns:1.3fr 1fr;gap:20px}.weather-current p{color:#dbeedb}.weather-circles{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.weather-circle{aspect-ratio:1;border-radius:50%;border:5px solid #bde775;display:grid;place-content:center;text-align:center;background:#1f6c4d;font-weight:800}.weather-circle small{font-size:10px;font-weight:400}.weather-grid{display:grid;grid-template-columns:1.3fr .7fr;gap:18px;margin-top:18px}.forecast-days{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.forecast-day{padding:12px 8px;text-align:center;border:1px solid #e0e8d8;border-radius:9px}.forecast-day.rainy{background:#eaf3df;border-color:#b9dca5}.forecast-day b,.forecast-day small{display:block;margin:4px}.rain-window{background:#e7f1d5}.bell{position:relative}.bell[data-count]:after{content:attr(data-count);position:absolute;right:-8px;top:-6px;background:#d95d38;color:#fff;border-radius:50%;font-size:10px;min-width:16px;height:16px;display:grid;place-content:center}@media(max-width:760px){.weather-current,.weather-grid{grid-template-columns:1fr}.weather-circles{grid-template-columns:repeat(2,1fr)}.forecast-days{grid-template-columns:repeat(2,1fr)}</style>');
  $("#appSide nav").insertAdjacentHTML("beforeend",'<button data-view="weather">☀ <span data-t="weather">Weather</span></button>');
  $("#appShell").insertAdjacentHTML("beforeend",'<section id="weather" class="view"><div class="view-heading"><div><p class="crumb">WEATHER / వాతావరణం</p><h2>Farm weather</h2><p>Live forecast for your selected farm location.</p></div><button class="secondary" id="refreshWeather">Refresh</button></div><section class="panel"><div class="weather-actions"><button class="primary" id="useWeatherLocation">📍 Use my farm location</button><button class="secondary" id="enableNotifications">🔔 Enable weather notifications</button></div><p class="muted" id="weatherLocationStatus">Location is requested only after you press the button.</p></section><div id="weatherContent" class="weather-content"><div class="empty-state">Use your farm location to load real weather from Open-Meteo.</div></div></section><dialog id="notificationDialog" class="editor-dialog"><button class="close">×</button><p class="label">NOTIFICATION CENTER</p><h2>Weather alerts</h2><button class="text" id="clearNotifications">Clear notifications</button><div id="notificationList" class="resource-list"></div></dialog>');
  document.querySelectorAll("[data-view]").forEach(button=>button.onclick=()=>view(button.dataset.view));
  $("#useWeatherLocation").onclick=requestWeatherLocation; $("#refreshWeather").onclick=()=>state.location?loadWeather():requestWeatherLocation(); $("#enableNotifications").onclick=enableWeatherNotifications;
  $(".bell").onclick=showNotifications; $("#notificationDialog .close").onclick=()=>$("#notificationDialog").close(); $("#clearNotifications").onclick=clearNotifications;
}
function weatherCacheKey(){return "rythu-weather-"+(state.farmer?.id||"guest");}
function displayWeather(data,cached=false) {
  const current=data.current, rain=current.rain_probability??"—", days=data.forecast||[];
  $("#weatherContent").innerHTML=`<section class="weather-current"><div><p class="label">CURRENT WEATHER · ${cached?"CACHED ":""}${safe(data.source)}</p><h2>${current.icon||"☁️"} ${current.temperature_c??"—"}°C · ${safe(current.condition||"Weather update")}</h2><p>Feels like ${current.feels_like_c??"—"}°C · precipitation ${current.precipitation_mm??"—"} mm</p><small>Updated: ${new Date(data.updated_at).toLocaleString()} · ${safe(data.forecast_disclaimer)}</small></div><div class="weather-circles"><div class="weather-circle">${rain}%<small>Rain chance</small></div><div class="weather-circle">${current.humidity_percent??"—"}%<small>Humidity</small></div><div class="weather-circle">${current.wind_speed_kmh??"—"}<small>Wind km/h</small></div><div class="weather-circle">${current.temperature_c??"—"}°<small>Temperature</small></div></div></section><div class="weather-grid"><section class="panel"><p class="label">10-DAY RAIN OUTLOOK</p><div class="forecast-days">${days.map(d=>`<article class="forecast-day ${(d.rain_probability||0)>=60?"rainy":""}"><small>${new Date(d.date+"T00:00:00").toLocaleDateString(undefined,{weekday:"short",day:"numeric"})}</small><b>${d.icon}</b><small>${d.min_temp_c}°–${d.max_temp_c}°</small><small>🌧 ${d.rain_probability??"—"}%</small><small>${d.precipitation_mm??"—"} mm</small><small>💨 ${d.wind_speed_kmh??"—"} km/h</small></article>`).join("")}</div></section><section class="panel rain-window"><p class="label">🌧️ RAIN WINDOW</p><h3>${data.rain_window?"Rain expected around "+data.rain_window.date:"No meaningful rain window found"}</h3><p>${data.rain_window?`${data.rain_window.rain_probability}% chance · ${data.rain_window.precipitation_mm} mm forecast`:"Forecasts can change; check again before planning."}</p><hr><p class="label">IRRIGATION ADVISORY</p><h3>${safe(data.advisory.crop)} crop selected</h3><p>${safe(data.advisory.text)}</p></section></div>`;
}
async function loadWeather() {
  if(!state.location)return; $("#weatherContent").innerHTML='<div class="empty-state">Loading live weather from Open-Meteo…</div>';
  try { const data=await call(`/weather?lat=${state.location.lat}&lon=${state.location.lon}&farmer_id=${state.farmer.id}`);localStorage.setItem(weatherCacheKey(),JSON.stringify(data));displayWeather(data);await loadNotifications();clearInterval(weatherTimer);weatherTimer=setInterval(loadWeather,30*60*1000); }
  catch(error){const cached=JSON.parse(localStorage.getItem(weatherCacheKey())||"null");if(cached){displayWeather(cached,true);$("#weatherLocationStatus").textContent="Weather data temporarily unavailable — showing saved forecast; it may be outdated.";}else $("#weatherContent").innerHTML='<div class="empty-state">Weather data temporarily unavailable. Try refresh later.</div>';toast(error.message);}
}
function requestWeatherLocation(){if(!navigator.geolocation){$("#weatherLocationStatus").textContent="Location is not supported by this browser.";return}$("#weatherLocationStatus").textContent="Requesting location permission…";navigator.geolocation.getCurrentPosition(p=>{state.location={lat:p.coords.latitude,lon:p.coords.longitude};$("#weatherLocationStatus").textContent="📍 Location detected. Approximate coordinates are used privately for weather.";loadWeather();},()=>$("#weatherLocationStatus").textContent="Location was not shared. You can continue using other Rythu Sodara features.",{enableHighAccuracy:false,timeout:12000,maximumAge:300000});}
async function enableWeatherNotifications(){if(!("Notification" in window)||!("serviceWorker" in navigator)){toast("Notifications are not supported by this browser.");return}if(Notification.permission==="default")await Notification.requestPermission();const permission=Notification.permission;await call("/notifications/subscribe",{method:"POST",body:JSON.stringify({farmer_id:state.farmer.id,permission})});if(permission==="granted"){toast("Weather notifications enabled.");if(state.location){const data=JSON.parse(localStorage.getItem(weatherCacheKey())||"null");if(data?.rain_window)navigator.serviceWorker.ready.then(reg=>reg.showNotification("Rythu Sodara weather",{body:`Rain may occur around ${data.rain_window.date}. Tap to view Weather.`,tag:"rythu-weather"}));}}else toast(permission==="denied"?"Notifications are blocked in browser settings.":"Notification permission was not granted.");}
async function loadNotifications(){if(!state.farmer)return;const items=await call("/notifications?farmer_id="+state.farmer.id);const unread=items.filter(x=>!x.is_read).length;$(".bell").dataset.count=unread||"";$("#notificationList").innerHTML=items.length?items.map(n=>`<article class="resource notification-item ${n.is_read?"":"unread"}"><div><h3>${n.category==="rain"?"🌧️":n.category==="wind"?"💨":n.category==="heat"?"🌡️":"💧"} ${safe(n.title)}</h3><p>${safe(n.body)}</p><small>${new Date(n.created_at).toLocaleString()}</small></div><button class="text" data-read="${n.id}">Mark read</button></article>`).join(""):'<div class="empty-state">No meaningful weather alerts yet.</div>';document.querySelectorAll("[data-read]").forEach(b=>b.onclick=async()=>{await call("/notifications/read",{method:"POST",body:JSON.stringify({farmer_id:state.farmer.id,alert_ids:[+b.dataset.read]})});loadNotifications();});}
async function showNotifications(){await loadNotifications();$("#notificationDialog").showModal();}
async function clearNotifications(){await call("/notifications/read",{method:"POST",body:JSON.stringify({farmer_id:state.farmer.id,clear_all:true})});loadNotifications();}
if("serviceWorker" in navigator){navigator.serviceWorker.register("/service-worker.js").catch(()=>{});navigator.serviceWorker.addEventListener("message",event=>{if(event.data?.type==="OPEN_WEATHER")view("weather");});}
addEventListener("online",()=>{if(state.location)loadWeather();});
setupWeatherUI();
function setupPersonalMode(){
  document.head.insertAdjacentHTML("beforeend",'<style>.mode-switch{display:flex;background:#e6eee4;border-radius:999px;padding:4px;gap:3px}.mode-switch button{border:0;border-radius:999px;padding:9px 14px;background:transparent;font-weight:800;color:#496152;transition:.3s}.mode-switch button.active{background:#176149;color:#fff;box-shadow:0 3px 10px #163b2a33}body.personal{background:#071522;color:#ecf5fc}body.personal header,body.personal .panel,body.personal .quick-card{background:#102437;color:#e9f4fa;border-color:#264257}body.personal .side{background:#091b2c}body.personal .side nav button.active{background:#1a4f51}body.personal .personal-view{display:block}body.personal .view:not(.personal-view){display:none!important}body.personal .view-heading p,body.personal .panel>p,body.personal .muted{color:#aabfcf}.personal-view{display:none}.finance-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.finance-card{padding:19px;border-radius:12px;background:#102b40;border:1px solid #27495e}.finance-card b{display:block;font-size:25px;margin-top:8px}.money-in{color:#73e49e}.money-out{color:#ff9878}.finance-chart{height:130px;display:flex;align-items:end;gap:25%;padding:15px}.finance-chart i{width:25%;background:#72dd9a;border-radius:7px 7px 0 0}.finance-chart i:last-child{background:#f48b70}.personal-nav{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.personal-nav button{border:1px solid #2c5064;background:#102437;color:#d8eaf4;padding:10px 13px;border-radius:7px}.personal-nav button.active{background:#1c765f;border-color:#52b68a}@media(max-width:800px){.finance-cards{grid-template-columns:1fr 1fr}}</style>');
  $("header .header-actions").insertAdjacentHTML("afterbegin",'<div class="mode-switch"><button id="farmMode">🌾 FARM</button><button id="personalMode">💰 PERSONAL</button></div>');
  $("#appShell").insertAdjacentHTML("beforeend",'<section id="personal" class="view personal-view"><div class="view-heading"><div><p class="crumb">PERSONAL FARM MANAGEMENT</p><h2>Farm money, clearly.</h2><p>All figures are farmer-entered actual values unless marked as estimates.</p></div><button class="primary" id="addTransaction">+ Add transaction</button></div><div class="personal-nav"><button data-personal="overview">Overview</button><button data-personal="transactions">Transactions</button><button data-personal="land">Land</button><button data-personal="profit">Crop Profit</button><button data-personal="wealth">Farm Wealth</button></div><div id="personalContent"></div></section>');
  $("#addTransaction").onclick=()=>transactionForm();
  $("#farmMode").onclick=()=>setMode("farm");$("#personalMode").onclick=()=>setMode("personal");document.querySelectorAll("[data-personal]").forEach(b=>b.onclick=()=>renderPersonal(b.dataset.personal));setMode(state.mode);
}
function setMode(mode){state.mode=mode;localStorage.setItem("rythu-mode",mode);document.body.classList.toggle("personal",mode==="personal");$("#farmMode").classList.toggle("active",mode==="farm");$("#personalMode").classList.toggle("active",mode==="personal");if(mode==="personal"){document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id==="personal"));renderPersonal("overview");}else view("dashboard");}
const rs=(n)=>"₹"+Number(n||0).toLocaleString("en-IN");
async function renderPersonal(tab){
  if(!state.farmer)return;document.querySelectorAll("[data-personal]").forEach(b=>b.classList.toggle("active",b.dataset.personal===tab));const root=$("#personalContent");
  const summary=await call("/finance/summary?farmer_id="+state.farmer.id);
  if(tab==="overview"){root.innerHTML=`<div class="finance-cards"><article class="finance-card"><small>Total Investment</small><b>${rs(summary.total_investment)}</b></article><article class="finance-card"><small>Total Income</small><b class="money-in">${rs(summary.total_income)}</b></article><article class="finance-card"><small>Total Expenses</small><b class="money-out">${rs(summary.total_expenses)}</b></article><article class="finance-card"><small>Net Cash Flow</small><b class="${summary.net_cash_flow>=0?"money-in":"money-out"}">${rs(summary.net_cash_flow)}</b></article></div><div class="grid two"><section class="panel"><p class="label">CASH FLOW</p><div class="finance-chart"><i style="height:${summary.total_income?Math.min(100,30+summary.total_income/(Math.max(summary.total_income,summary.total_expenses)||1)*70):5}%"></i><i style="height:${summary.total_expenses?Math.min(100,30+summary.total_expenses/(Math.max(summary.total_income,summary.total_expenses)||1)*70):5}%"></i></div><p class="money-in">Income ${rs(summary.total_income)}</p><p class="money-out">Expenses ${rs(summary.total_expenses)}</p></section><section class="panel"><p class="label">CURRENT SUMMARY</p><h3>${summary.transaction_count?"Farm finance is active":"No transactions yet"}</h3><p>Largest expense: ${safe(summary.largest_expense_category||"Add an expense")}</p><p>Highest-income crop: ${safe(summary.highest_income_crop||"Add crop income")}</p><small>${safe(summary.label)}</small></section></div>`;}
  if(tab==="transactions"){
    const items=await call("/finance/transactions?farmer_id="+state.farmer.id);
    root.innerHTML='<section class="panel"><p class="label">TRANSACTIONS</p><input id="transactionSearch" placeholder="Search category or note"><div id="transactionList" class="resource-list"></div></section>';
    const draw=()=>{
      const search=$("#transactionSearch").value.toLowerCase();
      const filtered=items.filter(item=>JSON.stringify(item).toLowerCase().includes(search));
      $("#transactionList").innerHTML=filtered.map(item=>`<article class="resource"><div><h3 class="${item.type==="IN"?"money-in":"money-out"}">${item.type==="IN"?"IN ↑":"OUT ↓"} · ${safe(item.category)} · ${rs(item.amount)}</h3><p>${safe(item.date)} · ${safe(item.note||"No note")}</p></div><div><button class="text" data-edit-t="${item.id}">Edit</button> <button class="text" data-del-t="${item.id}">Delete</button></div></article>`).join("")||'<div class="empty-state">Add a transaction to see your cash flow.</div>';
      document.querySelectorAll("[data-del-t]").forEach(button=>button.onclick=async()=>{if(confirm("Delete this transaction?")){await fetch(API+"/finance/transactions/"+button.dataset.delT+"?farmer_id="+state.farmer.id,{method:"DELETE"});renderPersonal("transactions");}});
      document.querySelectorAll("[data-edit-t]").forEach(button=>button.onclick=()=>transactionForm(items.find(item=>item.id==button.dataset.editT)));
    };
    draw();$("#transactionSearch").oninput=draw;
  }
  if(tab==="profit"){root.innerHTML=`<section class="panel"><p class="label">CROP-WISE PROFIT</p>${summary.crop_profit.map(x=>`<article class="resource"><div><h3>${safe(x.crop)}</h3><p>Investment ${rs(x.investment)} · Income ${rs(x.income)}</p></div><b class="${x.net_profit>=0?"money-in":"money-out"}">${rs(x.net_profit)}</b></article>`).join("")||'<div class="empty-state">Add crop expenses and sales to see crop-wise profit.</div>'}</section>`;}
  if(tab==="land"){const lands=await call("/finance/land?farmer_id="+state.farmer.id);root.innerHTML=`<section class="panel"><p class="label">FARM LAND</p><h3>Total land: ${lands.reduce((n,x)=>n+x.area_acres,0).toFixed(2)} acres · ${lands.length} fields</h3>${lands.map(x=>`<article class="resource"><div><h3>${safe(x.name)} · ${x.area_acres} acres</h3><p>${safe(x.location)} · ${safe(x.crops.join(", ")||"No crop assigned")}</p></div></article>`).join("")||'<div class="empty-state">Add your land details in My Farm.</div>'}</section>`;}
  if(tab==="wealth"){const a=await call("/finance/assets?farmer_id="+state.farmer.id);root.innerHTML=`<section class="panel"><p class="label">FARM WEALTH</p><h3>Estimated farm assets: ${rs(a.estimated_total)}</h3><p>${a.label}. Not market verified.</p><form id="assetForm" class="editor-grid">${["land_value","machinery_value","livestock_value","crop_value","farm_cash"].map(k=>`<label>${k.replace("_"," ")}<input type="number" min="0" name="${k}" value="${a[k]}"></label>`).join("")}<button class="primary" type="submit">Save asset values</button></form></section>`;$("#assetForm").onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=Number(data[k])||0);await call("/finance/assets?farmer_id="+state.farmer.id,{method:"PUT",body:JSON.stringify(data)});toast("Farm asset values saved.");renderPersonal("wealth");};}
}
function transactionForm(item=null){const t=item||{type:"OUT",amount:"",category:"Seeds",date:new Date().toISOString().slice(0,10),crop_id:"",field_id:"",buyer:"",note:""};const d=document.createElement("dialog");d.className="editor-dialog";d.innerHTML=`<button class="close">×</button><h2>${item?"Edit":"Add"} transaction</h2><form id="txnForm" class="editor-grid"><label>Type<select name="type"><option ${t.type==="IN"?"selected":""}>IN</option><option ${t.type==="OUT"?"selected":""}>OUT</option></select></label><label>Amount<input name="amount" type="number" min=".01" step=".01" value="${t.amount}" required></label><label>Category<input name="category" value="${safe(t.category)}" required placeholder="Seeds, Labour, Crop Sale…"></label><label>Date<input name="transaction_date" type="date" value="${t.date}" required></label><label>Crop<select name="crop_id"><option value="">Not linked</option>${state.crop?`<option value="${state.crop.id}" ${t.crop_id===state.crop.id?"selected":""}>${safe(state.crop.name)}</option>`:""}</select></label><label>Buyer<input name="buyer" value="${safe(t.buyer||"")}"></label><label class="wide">Notes<textarea name="note">${safe(t.note||"")}</textarea></label><button class="primary" type="submit">Save</button></form>`;document.body.append(d);d.showModal();d.querySelector(".close").onclick=()=>d.close();d.querySelector("form").onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.amount=Number(data.amount);data.crop_id=data.crop_id?Number(data.crop_id):null;data.field_id=null;data.buyer=data.buyer||null;let url="/finance/transactions"+(item?"/"+item.id:"")+"?farmer_id="+state.farmer.id;await call(url,{method:item?"PUT":"POST",body:JSON.stringify(data)});d.close();toast("Transaction saved.");renderPersonal("transactions");};}
setupPersonalMode();

