const personalText={English:{overview:"Overview",finance:"Finance",transactions:"Transactions",land:"Land",profit:"Crop Profit",wealth:"Farm Wealth",settings:"Settings & goals",income:"Total Income",expenses:"Total Expenses",investment:"Total Farm Investment",cash:"Net Cash Flow",profitLabel:"Estimated Profit",assets:"Farm Assets",add:"Add transaction",none:"No transactions recorded yet",addFirst:"Add your first transaction",incomeAdded:"Farm income added to financial overview",noIncome:"No farm income recorded yet."},Telugu:{overview:"సారాంశం",finance:"ఆర్థికం",transactions:"లావాదేవీలు",land:"భూమి",profit:"పంట లాభం",wealth:"వ్యవసాయ ఆస్తులు",settings:"లక్ష్యాలు",income:"మొత్తం ఆదాయం",expenses:"మొత్తం ఖర్చులు",investment:"మొత్తం పెట్టుబడి",cash:"నికర నగదు ప్రవాహం",profitLabel:"అంచనా లాభం",assets:"వ్యవసాయ ఆస్తులు",add:"లావాదేవీ జోడించండి",none:"ఇంకా లావాదేవీలు లేవు",addFirst:"మీ మొదటి లావాదేవీ జోడించండి",incomeAdded:"వ్యవసాయ ఆదాయం ఆర్థిక సారాంశంలో చూపబడింది",noIncome:"వ్యవసాయ ఆదాయం ఇంకా నమోదు కాలేదు."}};
const pt=(key)=>personalText[state.language][key]||key;
function upgradePersonalMode(){
  document.head.insertAdjacentHTML("beforeend",`<style>
  .mode-switch{position:relative;isolation:isolate;overflow:hidden;min-width:210px}.mode-switch:before{content:"";position:absolute;z-index:-1;inset:4px auto 4px 4px;width:calc(50% - 4px);border-radius:999px;background:#176149;transition:transform .55s cubic-bezier(.2,.8,.2,1),background .45s,box-shadow .45s}.mode-switch.personal-switch:before{transform:translateX(100%);background:linear-gradient(135deg,#8d55ff,#d35bff);box-shadow:0 0 18px #bb6cff}.mode-switch button{width:50%;position:relative;z-index:1}.mode-switch button.active{background:transparent;box-shadow:none}.personal{background:radial-gradient(circle at 80% 0,#59248b 0,transparent 30%),radial-gradient(circle at 0% 100%,#201556 0,transparent 38%),#0d0920!important;transition:background .6s ease}.personal header,.personal .panel,.personal .quick-card{background:linear-gradient(135deg,#1b1238eF,#221544eF)!important;border-color:#7653b344!important;box-shadow:0 10px 28px #0803124d}.personal .side{background:linear-gradient(180deg,#120a2b,#0b0920)!important}.personal .side nav button.active,.personal .personal-nav button.active{background:linear-gradient(135deg,#814dff,#bd55df)!important;box-shadow:0 0 22px #a85dff80!important;color:#fff!important}.personal .personal-view{display:block}.personal .finance-card,.personal .finance-action{background:linear-gradient(140deg,#241849eF,#30215dE8);border:1px solid #9e78e650;color:#f9f5ff;box-shadow:inset 0 1px #ffffff18,0 12px 28px #09031655;transition:transform .2s,box-shadow .2s,border-color .2s}.personal .finance-card,.personal button,.personal .personal-nav button{cursor:pointer}.personal .finance-card:hover,.personal .finance-card:focus-visible,.personal .finance-action:hover,.personal .personal-nav button:hover,.personal button:focus-visible{transform:translateY(-3px);border-color:#e6b5ff!important;box-shadow:0 0 0 3px #bd6cff33,0 12px 34px #a854ff4d!important;outline:0}.personal .personal-nav{gap:10px}.personal .personal-nav button{color:#eee7ff;background:#21163f;border-color:#7654a7;transition:.25s;min-height:42px}.personal .primary{background:linear-gradient(135deg,#a961ff,#e05eff);border:0;box-shadow:0 6px 20px #a44bff66}.personal .empty-state{color:#d9cff8;background:#211744;border-color:#805ab5}.personal .resource{background:#1b1335;border-color:#65499a}.finance-cards{grid-template-columns:repeat(3,minmax(0,1fr))}.finance-card{border-radius:16px;text-align:left;font:inherit}.finance-card b{font-size:24px}.finance-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0}.finance-action{padding:16px;border-radius:14px;text-align:left}.finance-action b{display:block;font-size:19px;margin-top:5px}.personal-chart{display:flex;height:145px;align-items:flex-end;gap:12px;padding:16px;border-radius:12px;background:#130e2d}.personal-chart div{flex:1;text-align:center;font-size:11px;color:#d8c9fb}.personal-chart i{display:block;min-height:4px;border-radius:8px 8px 2px 2px;background:linear-gradient(#9e6aff,#dd6bff);margin-bottom:8px}.personal-chart div.expense i{background:linear-gradient(#ff866c,#ef4f74)}.flow-overlay{position:fixed;inset:0;z-index:50;display:grid;place-items:center;background:#0a0619dd;backdrop-filter:blur(8px);animation:fadeIn .25s}.flow-card{width:min(390px,88vw);padding:30px;border-radius:24px;text-align:center;background:linear-gradient(145deg,#2d195b,#140d32);border:1px solid #be81ff;box-shadow:0 0 45px #9a51ff88;color:#fff}.flow-amount{font-size:38px;color:#7ee6a7;margin:16px}.flow-arrow{font-size:30px;color:#e29aff;animation:flow 1s infinite}.goal-progress{height:9px;background:#180f32;border-radius:9px;overflow:hidden}.goal-progress i{display:block;height:100%;background:linear-gradient(90deg,#985cff,#e270ff)}@keyframes flow{50%{transform:translateY(8px);opacity:.45}}@keyframes fadeIn{from{opacity:0}}@media(max-width:760px){.finance-cards,.finance-actions{grid-template-columns:1fr 1fr}.mode-switch{min-width:175px}.mode-switch button{font-size:11px;padding:8px 4px!important}}</style>`);
  $("#personal").querySelector(".view-heading").innerHTML=`<div><p class="crumb">💜 PERSONAL FINANCE</p><h2>Farm money, clearly.</h2><p>Only your recorded transactions are used.</p></div><button class="primary" id="addTransaction">+ ${pt("add")}</button>`;
  $("#personal .personal-nav").innerHTML=["overview","finance","transactions","land","profit","wealth","settings"].map(x=>`<button data-personal="${x}">${pt(x)}</button>`).join("");
  $("#addTransaction").onclick=()=>transactionForm();
  document.querySelectorAll("[data-personal]").forEach(b=>b.onclick=()=>renderPersonal(b.dataset.personal));
}
async function showIncomeFlow(){const records=await call("/finance/transactions?farmer_id="+state.farmer.id+"&type=IN");const latest=records[0];const card=document.createElement("div");card.className="flow-overlay";card.innerHTML=`<div class="flow-card"><small>🌾 FARM EARNINGS</small><div class="flow-arrow">↓</div><div class="flow-amount">${latest?rs(latest.amount):"—"}</div><div class="flow-arrow">↓</div><b>💜 PERSONAL FINANCE</b><p>${latest?pt("incomeAdded"):pt("noIncome")}</p><button class="primary">Continue</button></div>`;document.body.append(card);card.querySelector("button").onclick=()=>card.remove();setTimeout(()=>card.remove(),3200);}
function setMode(mode){const changed=state.mode!==mode;state.mode=mode;localStorage.setItem("rythu-mode",mode);document.body.classList.toggle("personal",mode==="personal");$(".mode-switch").classList.toggle("personal-switch",mode==="personal");$("#farmMode").classList.toggle("active",mode==="farm");$("#personalMode").classList.toggle("active",mode==="personal");if(mode==="personal"){document.querySelectorAll(".view").forEach(x=>x.classList.toggle("active",x.id==="personal"));renderPersonal("overview");if(changed&&state.farmer)showIncomeFlow();}else view("dashboard");}
async function renderPersonal(tab){
 if(!state.farmer)return;document.querySelectorAll("[data-personal]").forEach(b=>b.classList.toggle("active",b.dataset.personal===tab));const root=$("#personalContent");root.innerHTML='<div class="empty-state">Loading your financial records…</div>';
 try{const summary=await call("/finance/summary?farmer_id="+state.farmer.id);const profit=summary.net_cash_flow;const card=(label,value,go,klass="")=>`<button class="finance-card ${klass}" data-go="${go}"><small>${label}</small><b>${rs(value)}</b></button>`;
 if(tab==="overview"){root.innerHTML=`<div class="finance-cards">${card(pt("investment"),summary.total_investment,"finance","money-out")}${card(pt("income"),summary.total_income,"finance","money-in")}${card(pt("expenses"),summary.total_expenses,"finance","money-out")}${card(pt("cash"),summary.net_cash_flow,"finance",profit>=0?"money-in":"money-out")}${card(pt("profitLabel"),profit,"profit",profit>=0?"money-in":"money-out")}${card(pt("assets"),0,"wealth")}</div><div class="finance-actions"><button class="finance-action" data-go="finance">Income & expenses<b>Record money in or out</b></button><button class="finance-action" data-go="transactions">Transactions<b>Search and edit records</b></button><button class="finance-action" data-go="settings">Goals<b>Plan with real cash flow</b></button></div><section class="panel"><p class="label">INCOME VS EXPENSES</p>${summary.transaction_count?barChart([['Income',summary.total_income,'income'],['Expenses',summary.total_expenses,'expense']]):`<div class="empty-state">${pt("none")} — ${pt("addFirst")}.</div>`}</section>`;document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>renderPersonal(b.dataset.go));}
 if(tab==="finance"){root.innerHTML=`<section class="panel"><p class="label">FINANCE</p><h3>Record actual farm money</h3><p>Income: crop sale, buyer payment, subsidy or other. Expenses: seeds, fertilizer, pesticide, labour, irrigation, fuel, storage and more.</p><button class="primary" id="financeAdd">+ ${pt("add")}</button></section><section class="panel"><p class="label">FINANCIAL SUMMARY</p>${barChart([['Income',summary.total_income,'income'],['Expenses',summary.total_expenses,'expense'],['Cash flow',Math.abs(summary.net_cash_flow),summary.net_cash_flow>=0?'income':'expense']])}</section>`;$("#financeAdd").onclick=()=>transactionForm();}
 if(tab==="transactions")await renderTransactions(root);
 if(tab==="land")await renderLand(root);
 if(tab==="profit"){root.innerHTML=`<section class="panel"><p class="label">CROP-WISE PROFIT</p>${summary.crop_profit.filter(x=>x.transaction_count).map(x=>`<button class="resource finance-card" data-crop-profit="${x.crop_id}"><div><h3>${safe(x.crop)}</h3><p>Investment ${rs(x.investment)} · Income ${rs(x.income)} · Expenses ${rs(x.expenses)}</p></div><b class="${x.net_profit>=0?'money-in':'money-out'}">${rs(x.net_profit)}</b></button>`).join("")||'<div class="empty-state">No crop profit data yet. Link a crop when you add income or expenses.</div>'}</section>`;document.querySelectorAll("[data-crop-profit]").forEach(b=>b.onclick=()=>renderTransactions(root,b.dataset.cropProfit));}
 if(tab==="wealth")await renderWealth(root);
 if(tab==="settings")await renderGoals(root);
 }catch(error){root.innerHTML=`<div class="empty-state">Could not load Personal records: ${safe(error.message)}</div>`;}
}
function barChart(rows){const max=Math.max(1,...rows.map(x=>Number(x[1])||0));return `<div class="personal-chart">${rows.map(x=>`<div class="${x[2]}"><i style="height:${Math.max(4,(Number(x[1])/max)*100)}%"></i>${safe(x[0])}<br>${rs(x[1])}</div>`).join("")}</div>`;}
async function renderTransactions(root,cropId=""){const items=await call("/finance/transactions?farmer_id="+state.farmer.id+(cropId?"&crop_id="+cropId:""));const categories=[...new Set(items.map(x=>x.category))];root.innerHTML=`<section class="panel"><p class="label">TRANSACTIONS</p><div class="editor-grid"><label>Search<input id="txSearch" placeholder="Category, buyer or note"></label><label>Type<select id="txType"><option value="">All</option><option value="IN">Income</option><option value="OUT">Expense</option></select></label><label>Category<select id="txCategory"><option value="">All categories</option>${categories.map(x=>`<option>${safe(x)}</option>`).join("")}</select></label><label>Sort<select id="txSort"><option value="new">Newest first</option><option value="old">Oldest first</option></select></label></div><div id="transactionList" class="resource-list"></div></section>`;const draw=()=>{let list=items.filter(x=>(!$("#txSearch").value||JSON.stringify(x).toLowerCase().includes($("#txSearch").value.toLowerCase()))&&(!$("#txType").value||x.type===$("#txType").value)&&(!$("#txCategory").value||x.category===$("#txCategory").value));if($("#txSort").value==="old")list.reverse();$("#transactionList").innerHTML=list.map(x=>`<article class="resource"><div><h3 class="${x.type==='IN'?'money-in':'money-out'}">${x.type==='IN'?'IN ↑':'OUT ↓'} · ${safe(x.category)} · ${rs(x.amount)}</h3><p>${safe(x.date)} · Buyer: ${safe(x.buyer||'—')} · ${safe(x.note||'No note')}</p></div><div><button class="text" data-edit-t="${x.id}">Edit</button> <button class="text" data-del-t="${x.id}">Delete</button></div></article>`).join("")||`<div class="empty-state">${pt("none")} — ${pt("addFirst")}.</div>`;document.querySelectorAll("[data-edit-t]").forEach(b=>b.onclick=()=>transactionForm(items.find(x=>x.id==b.dataset.editT)));document.querySelectorAll("[data-del-t]").forEach(b=>b.onclick=async()=>{if(confirm('Delete this transaction?')){await call('/finance/transactions/'+b.dataset.delT+'?farmer_id='+state.farmer.id,{method:'DELETE'});renderTransactions(root,cropId);}});};["txSearch","txType","txCategory","txSort"].forEach(id=>$("#"+id).oninput=draw);draw();}
async function renderLand(root){const fields=await call('/finance/land?farmer_id='+state.farmer.id);const owned=fields.filter(x=>x.ownership==='Owned').reduce((n,x)=>n+x.area_acres,0),leased=fields.filter(x=>x.ownership==='Leased').reduce((n,x)=>n+x.area_acres,0);root.innerHTML=`<section class="panel"><p class="label">LAND</p><h3>${(owned+leased).toFixed(2)} acres · ${owned.toFixed(2)} owned · ${leased.toFixed(2)} leased · ${fields.length} fields</h3><button class="primary" id="addLand">+ Add land details</button>${fields.map(x=>`<article class="resource"><div><h3>${safe(x.name)} · ${x.area_acres} acres · ${safe(x.ownership)}</h3><p>${safe(x.location)} · ${safe(x.crops.join(', ')||'No crop assigned')} · ${safe(x.notes||'No notes')}</p></div><button class="text" data-edit-land="${x.id}">Edit</button></article>`).join("")||'<div class="empty-state">Add your land details.</div>'}</section>`;$("#addLand").onclick=()=>landForm();document.querySelectorAll('[data-edit-land]').forEach(b=>b.onclick=()=>landForm(fields.find(x=>x.id==b.dataset.editLand)));}
function landForm(field=null){const f=field||{name:'',area_acres:'',location:state.farmer.village||'',ownership:'Owned',notes:''};const d=document.createElement('dialog');d.className='editor-dialog';d.innerHTML=`<button class="close">×</button><h2>${field?'Edit':'Add'} land</h2><form class="editor-grid"><label>Field name<input name="name" required value="${safe(f.name)}"></label><label>Area (acres)<input name="area_acres" type="number" min=".01" step=".01" required value="${f.area_acres}"></label><label>Village/location<input name="location" required value="${safe(f.location)}"></label><label>Land type<select name="ownership"><option ${f.ownership==='Owned'?'selected':''}>Owned</option><option ${f.ownership==='Leased'?'selected':''}>Leased</option></select></label><label class="wide">Notes<textarea name="notes">${safe(f.notes)}</textarea></label><button class="primary">Save land</button><button type="button" class="text cancel">Cancel</button></form>`;document.body.append(d);d.showModal();d.querySelector('.close').onclick=()=>d.remove();d.querySelector('.cancel').onclick=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));data.area_acres=Number(data.area_acres);await call('/finance/land'+(field?'/'+field.id:'')+'?farmer_id='+state.farmer.id,{method:field?'PUT':'POST',body:JSON.stringify(data)});d.remove();renderPersonal('land');};}
async function renderWealth(root){const a=await call('/finance/assets?farmer_id='+state.farmer.id);root.innerHTML=`<section class="panel"><p class="label">FARM WEALTH</p><h3>Estimated farm assets: ${rs(a.estimated_total)}</h3><p>Farmer-entered estimate. Not a verified market value.</p><form id="assetForm" class="editor-grid">${['land_value','machinery_value','livestock_value','crop_value','farm_cash'].map(k=>`<label>${k.replaceAll('_',' ')}<input type="number" min="0" name="${k}" value="${a[k]}"></label>`).join('')}<button class="primary">Save estimates</button></form></section>`;$("#assetForm").onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>data[k]=Number(data[k])||0);await call('/finance/assets?farmer_id='+state.farmer.id,{method:'PUT',body:JSON.stringify(data)});toast('Farm asset estimates saved.');renderPersonal('wealth');};}
async function renderGoals(root){const goals=await call('/finance/goals?farmer_id='+state.farmer.id);root.innerHTML=`<section class="panel"><p class="label">FINANCIAL GOALS</p><p>Progress uses your actual recorded net cash flow.</p><button class="primary" id="addGoal">+ Add goal</button>${goals.map(g=>`<article class="resource"><div><h3>${safe(g.name)} · ${rs(g.target_amount)}</h3><div class="goal-progress"><i style="width:${Math.min(100,(g.progress_amount/g.target_amount)*100)}%"></i></div><p>${rs(g.progress_amount)} recorded cash flow</p></div><button class="text" data-del-goal="${g.id}">Delete</button></article>`).join('')||'<div class="empty-state">Add a savings, equipment, or future farm investment goal.</div>'}</section>`;$("#addGoal").onclick=()=>goalForm();document.querySelectorAll('[data-del-goal]').forEach(b=>b.onclick=async()=>{await call('/finance/goals/'+b.dataset.delGoal+'?farmer_id='+state.farmer.id,{method:'DELETE'});renderGoals(root);});}
function goalForm(){const d=document.createElement('dialog');d.className='editor-dialog';d.innerHTML='<button class="close">×</button><h2>Add financial goal</h2><form class="editor-grid"><label>Goal<input name="name" required placeholder="Equipment, savings…"></label><label>Target amount<input name="target_amount" type="number" min="1" required></label><button class="primary">Save goal</button></form>';document.body.append(d);d.showModal();d.querySelector('.close').onclick=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.target_amount=Number(x.target_amount);await call('/finance/goals?farmer_id='+state.farmer.id,{method:'POST',body:JSON.stringify(x)});d.remove();renderPersonal('settings');};}
function transactionForm(item=null){const t=item||{type:'OUT',amount:'',category:'Seeds',date:new Date().toISOString().slice(0,10),crop_id:'',field_id:'',buyer:'',note:''};const cropOptions=state.crop?`<option value="${state.crop.id}" ${String(t.crop_id)===String(state.crop.id)?'selected':''}>${safe(state.crop.name)}</option>`:'';const d=document.createElement('dialog');d.className='editor-dialog';d.innerHTML=`<button class="close">×</button><h2>${item?'Edit':'Add'} transaction</h2><form class="editor-grid"><label>Type<select name="type"><option ${t.type==='IN'?'selected':''}>IN</option><option ${t.type==='OUT'?'selected':''}>OUT</option></select></label><label>Amount<input name="amount" type="number" min=".01" step=".01" value="${t.amount}" required></label><label>Category<select name="category"><option>${safe(t.category)}</option><option>Crop Sale</option><option>Buyer Payment</option><option>Subsidy/Support</option><option>Seeds</option><option>Fertilizer</option><option>Pesticides</option><option>Labour</option><option>Irrigation</option><option>Electricity</option><option>Fuel</option><option>Machinery</option><option>Transport</option><option>Storage</option><option>Land Lease</option><option>Maintenance</option><option>Other</option></select></label><label>Date<input name="transaction_date" type="date" value="${t.date}" required></label><label>Crop<select name="crop_id"><option value="">Not linked</option>${cropOptions}</select></label><label>Buyer<input name="buyer" value="${safe(t.buyer||'')}"></label><label class="wide">Note<textarea name="note">${safe(t.note||'')}</textarea></label><button class="primary">Save</button><button class="text cancel" type="button">Cancel</button></form>`;document.body.append(d);d.showModal();d.querySelector('.close').onclick=()=>d.remove();d.querySelector('.cancel').onclick=()=>d.remove();d.querySelector('form').onsubmit=async e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));x.amount=Number(x.amount);x.crop_id=x.crop_id?Number(x.crop_id):null;x.field_id=null;x.buyer=x.buyer||null;await call('/finance/transactions'+(item?'/'+item.id:'')+'?farmer_id='+state.farmer.id,{method:item?'PUT':'POST',body:JSON.stringify(x)});d.remove();toast('Transaction saved.');renderPersonal('transactions');};}
upgradePersonalMode();
bindAuth(); applyLanguage(); network(); if(state.farmer)startApp(state.farmer).catch(()=>{localStorage.removeItem("rythu-farmer");state.farmer=null;});
